NI = "class NI:\n    def __init__(self, x): self.x = x\n    def isInteger(self): return not isinstance(self.x, list)\n    def getInteger(self): return self.x\n    def getList(self): return [NI(y) for y in self.x]\n"
def ITER(cls, arg): return NI + "it=%s(%s)\nout=[]\nwhile it.hasNext(): out.append(it.next())\nRESULT=out" % (cls, arg)
ROB = "class Robot:\n    def __init__(self, room, r, c):\n        self.room, self.r, self.c, self.d = room, r, c, 0\n        self.cleaned = set()\n        self.dirs = ((-1, 0), (0, 1), (1, 0), (0, -1))\n    def move(self):\n        nr, nc = self.r + self.dirs[self.d][0], self.c + self.dirs[self.d][1]\n        if 0 <= nr < len(self.room) and 0 <= nc < len(self.room[0]) and self.room[nr][nc]:\n            self.r, self.c = nr, nc\n            return True\n        return False\n    def turnLeft(self): self.d = (self.d - 1) % 4\n    def turnRight(self): self.d = (self.d + 1) % 4\n    def clean(self): self.cleaned.add((self.r, self.c))\n"
def ROBOT(room, r, c): return ROB + "room=%s\nrb=Robot(room,%d,%d)\nSolution().cleanRoom(rb)\nRESULT=[len(rb.cleaned), sum(map(sum, room))]" % (room, r, c)
